function parseMoods(value:string[]|string|null|undefined):string[]{if(Array.isArray(value))return value;return typeof value==='string'&&value?value.split(','):[];}
function severityFromNotes(value:string|null|undefined):string{return value?.match(/severity:\s*(mild|moderate|severe)/i)?.[1]?.toLowerCase()??'mild';}
function cycleDayAt(start:string|null|undefined,date:string){if(!start)return null;return Math.floor((new Date(date+'T12:00:00').getTime()-new Date(start+'T12:00:00').getTime())/86400000)+1;}
