 async function toggleAstrology(){setBusy(true);setError('');try{const response=await fetch('/api/cycle-profile',{method:'PUT',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf()},body:JSON.stringify({average_cycle_length:data.profile.average_cycle_length,average_period_length:data.profile.average_period_length,cycle_regularity:data.profile.cycle_regularity,timezone:data.profile.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',wants_astrology:!astrology,birth_date:data.profile.birth_date,birth_time:data.profile.birth_time?.slice(0,5)??null,birth_place:data.profile.birth_place,onboarding_completed:true})});const result=await response.json();if(!response.ok)throw new Error(errorText(result,'Astrology preference could not be updated.'));setAstrology(!astrology);await onRefresh();setNotice(!astrology?'Your cosmic extras are switched on. ✨':'Astrology is off. Your cycle tools remain unchanged.');}catch(e){setError(e instanceof Error?e.message:'Could not update astrology preference.');}finally{setBusy(false);}}
