 async function saveSymptoms(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setError('');try{const logDate=selectedDate>today?today:selectedDate;const all=Array.from(new Set([...pickedSymptoms,...selectedMoodSymptoms(symptomMood)]));const noteLines=symptomNotes.split('\n').filter(line=>!/^Symptom severity:/i.test(line));const notes=[...noteLines,...(all.length?['Symptom severity: '+severity]:[])].filter(Boolean).join('\n')||null;const response=await fetch('/api/daily-checkins',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf()},body:JSON.stringify({log_date:logDate,symptoms:all,mood:symptomMood.length?symptomMood:null,notes})});const result=await response.json();if(!response.ok)throw new Error(errorText(result,'Symptoms could not be saved.'));setSelectedCheckin(result.checkin??null);setHistoryRefresh(value=>value+1);if(logDate===today){setCheckinNotes(result.checkin?.notes??'');setMood(result.checkin?.mood??[]);setEnergy(result.checkin?.energy_level??'');setSavedCheckin(true);}await onRefresh();setModal(null);setNotice('Your symptom notes are saved privately. ✧');}catch(e){setError(e instanceof Error?e.message:'Your symptom notes could not be saved.');}finally{setBusy(false);}}
